// BatFix - native Win32 single-file .bat/.cmd encoding normalizer
// Build: cl.exe /std:c++17 /MT /O2 /EHsc /utf-8 /DUNICODE /D_UNICODE BatFix.cpp
// Links only against OS DLLs (kernel32/user32/gdi32/comdlg32/shell32).
#define WIN32_LEAN_AND_MEAN
#define UNICODE
#define _UNICODE
#include <windows.h>
#include <commdlg.h>
#include <shellapi.h>
#include <string>
#include <vector>
#include <algorithm>
#include <cwctype>
#include <cstdio>
#include <cwchar>
#include <cstdlib>
#include "version.h"        // generated by build.ps1 from the VERSION file

#pragma comment(lib, "kernel32.lib")
#pragma comment(lib, "user32.lib")
#pragma comment(lib, "gdi32.lib")
#pragma comment(lib, "comdlg32.lib")
#pragma comment(lib, "shell32.lib")

using W = std::wstring;
using Bytes = std::string;

// ------------------------------------------------------------------ helpers
static bool IsWs(wchar_t c) { return c == L' ' || c == L'\t'; }
static W TrimL(const W& s) { size_t i = 0; while (i < s.size() && IsWs(s[i])) ++i; return s.substr(i); }
static W TrimR(const W& s) { size_t n = s.size(); while (n && IsWs(s[n - 1])) --n; return s.substr(0, n); }
static W Trim(const W& s) { return TrimR(TrimL(s)); }
static W Lower(W s) { for (auto& c : s) c = (wchar_t)towlower(c); return s; }
static bool StartsCI(const W& s, const W& p) {
    if (s.size() < p.size()) return false;
    for (size_t i = 0; i < p.size(); ++i)
        if (towlower(s[i]) != towlower(p[i])) return false;
    return true;
}
static bool HasNonAscii(const W& s) { for (wchar_t c : s) if (c > 0x7F) return true; return false; }
static bool HasNonBmp(const W& s) {
    for (size_t i = 0; i + 1 < s.size(); ++i)
        if (s[i] >= 0xD800 && s[i] <= 0xDBFF && s[i + 1] >= 0xDC00 && s[i + 1] <= 0xDFFF) return true;
    return false;
}
static W Basename(const W& p) {
    size_t i = p.find_last_of(L"\\/");
    return i == W::npos ? p : p.substr(i + 1);
}
static bool IsBatFile(const W& p) {
    size_t d = p.rfind(L'.');
    if (d == W::npos) return false;
    W e = Lower(p.substr(d));
    return e == L".bat" || e == L".cmd";
}
static W Itow(long long v) { wchar_t b[64]; swprintf_s(b, L"%lld", v); return W(b); }

// ------------------------------------------------------------------ encoding
static bool Utf8ToWide(const char* p, int n, W& out, bool strict) {
    out.clear();
    if (n <= 0) return true;
    DWORD flags = strict ? MB_ERR_INVALID_CHARS : 0;
    int need = MultiByteToWideChar(CP_UTF8, flags, p, n, nullptr, 0);
    if (need <= 0) return false;
    out.resize((size_t)need);
    int got = MultiByteToWideChar(CP_UTF8, flags, p, n, &out[0], need);
    if (got <= 0) { out.clear(); return false; }
    out.resize((size_t)got);
    return true;
}
static bool AnsiToWide(UINT cp, const char* p, int n, W& out) {
    out.clear();
    if (n <= 0) return true;
    int need = MultiByteToWideChar(cp, 0, p, n, nullptr, 0);
    if (need <= 0) return false;
    out.resize((size_t)need);
    int got = MultiByteToWideChar(cp, 0, p, n, &out[0], need);
    if (got <= 0) { out.clear(); return false; }
    out.resize((size_t)got);
    return true;
}
static bool WideToUtf8(const W& s, Bytes& out) {
    out.clear();
    if (s.empty()) return true;
    int need = WideCharToMultiByte(CP_UTF8, 0, s.data(), (int)s.size(), nullptr, 0, nullptr, nullptr);
    if (need <= 0) return false;
    out.resize((size_t)need);
    WideCharToMultiByte(CP_UTF8, 0, s.data(), (int)s.size(), &out[0], need, nullptr, nullptr);
    return true;
}
static bool WideToAnsi(UINT cp, const W& s, Bytes& out) {
    out.clear();
    if (s.empty()) return true;
    int need = WideCharToMultiByte(cp, 0, s.data(), (int)s.size(), nullptr, 0, nullptr, nullptr);
    if (need <= 0) return false;
    out.resize((size_t)need);
    WideCharToMultiByte(cp, 0, s.data(), (int)s.size(), &out[0], need, nullptr, nullptr);
    return true;
}
static W Utf16BytesToWide(const unsigned char* p, size_t n, bool be) {
    W out; out.reserve(n / 2);
    for (size_t i = 0; i + 1 < n; i += 2) {
        unsigned b0 = p[i], b1 = p[i + 1];
        unsigned u = be ? ((b0 << 8) | b1) : ((b1 << 8) | b0);
        out.push_back((wchar_t)u);
    }
    return out;
}
static W Utf32BytesToWide(const unsigned char* p, size_t n, bool be) {
    W out; out.reserve(n / 4);
    for (size_t i = 0; i + 3 < n; i += 4) {
        unsigned b0 = p[i], b1 = p[i + 1], b2 = p[i + 2], b3 = p[i + 3];
        unsigned u = be ? (b0 << 24 | b1 << 16 | b2 << 8 | b3) : (b3 << 24 | b2 << 16 | b1 << 8 | b0);
        if (u > 0x10FFFF || (u >= 0xD800 && u <= 0xDFFF)) { out.push_back(L'\uFFFD'); continue; }
        if (u > 0xFFFF) {
            u -= 0x10000;
            out.push_back((wchar_t)(0xD800 + (u >> 10)));
            out.push_back((wchar_t)(0xDC00 + (u & 0x3FF)));
        } else out.push_back((wchar_t)u);
    }
    return out;
}

// ------------------------------------------------------------------ options / report
struct Options {
    bool manageChcp = true;
    bool fixLineTail = true;
    bool normalizeNewline = true;
    bool ensureTrailingCrlf = true;
    bool repairMojibake = false;
    bool backup = true;
    UINT ansiCp = 0;              // 0 = auto
    size_t maxBytes = 32u * 1024u * 1024u;
};
struct Report {
    W path;
    W enc = L"?";
    W bom = L"无";
    W newline = L"?";
    W chcp = L"-";
    int padded = 0;
    int rewritten = 0;
    int chcpTouched = 0;
    bool changed = false;
    bool backedUp = false;
    W backupPath;
    W result = L"OK";
    W message;
    std::vector<W> warns;
    void Warn(const W& w) { warns.push_back(w); }
};
static UINT EffectiveAnsiCp(const Options& o) {
    if (o.ansiCp) return o.ansiCp;
    UINT cp = GetACP();
    // If "Beta: Use Unicode UTF-8 for worldwide language support" is on,
    // legacy ANSI files are still almost certainly GBK on a Chinese machine.
    if (cp == 65001) cp = 936;
    if (cp == 0) cp = 936;
    return cp;
}

// ------------------------------------------------------------------ decode
enum class Enc { Empty, Utf8Bom, Utf8, Utf16Le, Utf16Be, Utf32Le, Utf32Be, Utf16LeRaw, Ansi, Binary };
struct Decoded { Enc e = Enc::Empty; W text; W name; size_t bomBytes = 0; };

static Decoded DecodeFile(const Bytes& raw, const Options& o, Report& r) {
    Decoded d;
    const unsigned char* p = (const unsigned char*)raw.data();
    size_t n = raw.size();
    if (n == 0) { d.e = Enc::Empty; d.name = L"空文件"; return d; }

    size_t off = 0;
    if (n >= 4 && p[0] == 0xFF && p[1] == 0xFE && p[2] == 0x00 && p[3] == 0x00) {
        d.e = Enc::Utf32Le; d.name = L"UTF-32 LE (BOM)"; off = 4;
    } else if (n >= 4 && p[0] == 0x00 && p[1] == 0x00 && p[2] == 0xFE && p[3] == 0xFF) {
        d.e = Enc::Utf32Be; d.name = L"UTF-32 BE (BOM)"; off = 4;
    } else if (n >= 3 && p[0] == 0xEF && p[1] == 0xBB && p[2] == 0xBF) {
        d.e = Enc::Utf8Bom; d.name = L"UTF-8 (BOM)"; off = 3;
    } else if (n >= 2 && p[0] == 0xFF && p[1] == 0xFE) {
        d.e = Enc::Utf16Le; d.name = L"UTF-16 LE (BOM)"; off = 2;
    } else if (n >= 2 && p[0] == 0xFE && p[1] == 0xFF) {
        d.e = Enc::Utf16Be; d.name = L"UTF-16 BE (BOM)"; off = 2;
    }
    d.bomBytes = off;
    if (off) r.bom = d.name;

    // Strip stacked UTF-8 BOMs (some editors add one on every save).
    if (d.e == Enc::Utf8Bom) {
        int stacked = 0;
        while (off + 3 <= n && p[off] == 0xEF && p[off + 1] == 0xBB && p[off + 2] == 0xBF) {
            off += 3; ++stacked;
        }
        if (stacked) r.Warn(L"检测到 " + Itow(stacked) + L" 个堆叠的 UTF-8 BOM，已一并移除");
        d.bomBytes = off;
    }

    const char* body = raw.data() + off;
    int bodyLen = (int)(n - off);

    switch (d.e) {
    case Enc::Utf32Le: d.text = Utf32BytesToWide(p + off, n - off, false); break;
    case Enc::Utf32Be: d.text = Utf32BytesToWide(p + off, n - off, true); break;
    case Enc::Utf16Le: d.text = Utf16BytesToWide(p + off, n - off, false); break;
    case Enc::Utf16Be: d.text = Utf16BytesToWide(p + off, n - off, true); break;
    case Enc::Utf8Bom:
        if (!Utf8ToWide(body, bodyLen, d.text, true)) {
            Utf8ToWide(body, bodyLen, d.text, false);
            r.Warn(L"BOM 声明 UTF-8，但正文含非法 UTF-8 字节，已按宽松方式解码");
        }
        break;
    default: {
        bool hasNul = false, hasHigh = false;
        size_t zeros = 0;
        for (size_t i = 0; i < n; ++i) {
            if (p[i] == 0) { hasNul = true; ++zeros; }
            if (p[i] >= 0x80) hasHigh = true;
        }
        if (hasNul) {
            // BOM-less UTF-16LE: require both a NUL high-byte ratio AND enough
            // (low byte printable + high byte zero) pairs. This rejects real
            // binaries like MZ headers that happen to contain NULs.
            size_t pairs = n / 2;
            size_t oddZero = 0, asciiPairs = 0;
            for (size_t i = 0; i + 1 < n; i += 2) {
                if (p[i + 1] == 0) {
                    ++oddZero;
                    unsigned char lo = p[i];
                    if (lo == 0x09 || lo == 0x0A || lo == 0x0D || (lo >= 0x20 && lo <= 0x7E))
                        ++asciiPairs;
                }
            }
            if (pairs && oddZero * 10 >= pairs * 3 && asciiPairs * 10 >= pairs * 3) {
                d.e = Enc::Utf16LeRaw;
                d.name = L"UTF-16 LE (无 BOM，推断)";
                d.text = Utf16BytesToWide(p, n, false);
                r.Warn(L"文件无 BOM 但含大量 NUL，按 UTF-16 LE 推断解码；如结果异常请检查");
                break;
            }
            d.e = Enc::Binary; d.name = L"二进制/未知";
            break;
        }
        W w;
        if (Utf8ToWide(raw.data(), (int)n, w, true)) {
            d.e = Enc::Utf8;
            d.name = hasHigh ? L"UTF-8 (无 BOM)" : L"纯 ASCII";
            d.text = w;
        } else {
            UINT cp = EffectiveAnsiCp(o);
            if (!AnsiToWide(cp, raw.data(), (int)n, d.text)) {
                d.e = Enc::Binary; d.name = L"解码失败";
                break;
            }
            d.e = Enc::Ansi;
            d.name = L"ANSI / CP" + Itow(cp) + (cp == 936 ? L" (GBK)" : L"");
            r.Warn(L"按 " + d.name + L" 解码 ANSI 源文件；若源语言不符可在界面切换源编码");
        }
        break;
    }
    }
    return d;
}

// ------------------------------------------------------------------ newline
static void AnalyzeNewline(const Bytes& raw, W& desc) {
    size_t crlf = 0, lf = 0, cr = 0;
    for (size_t i = 0; i < raw.size(); ++i) {
        if (raw[i] == '\r') {
            if (i + 1 < raw.size() && raw[i + 1] == '\n') { ++crlf; ++i; }
            else ++cr;
        } else if (raw[i] == '\n') ++lf;
    }
    if (!crlf && !lf && !cr) desc = L"无换行";
    else if (crlf && !lf && !cr) desc = L"CRLF";
    else if (lf && !crlf && !cr) desc = L"LF";
    else if (cr && !crlf && !lf) desc = L"CR";
    else desc = L"混合 (CRLF=" + Itow((long long)crlf) + L", LF=" + Itow((long long)lf) + L", CR=" + Itow((long long)cr) + L")";
}
static std::vector<W> SplitLines(const W& t) {
    std::vector<W> v;
    size_t start = 0;
    for (size_t i = 0; i < t.size();) {
        if (t[i] == L'\r') {
            v.push_back(t.substr(start, i - start));
            i += (i + 1 < t.size() && t[i + 1] == L'\n') ? 2 : 1;
            start = i;
        } else if (t[i] == L'\n') {
            v.push_back(t.substr(start, i - start));
            ++i; start = i;
        } else ++i;
    }
    if (start < t.size()) v.push_back(t.substr(start));
    return v;
}

// ------------------------------------------------------------------ chcp handling
// Only a line whose FIRST command token is exactly `chcp`/`chcp.com` is a
// standalone chcp command. This deliberately excludes `for /f ... ('chcp')`,
// `if ... chcp`, `echo chcp`, comments, and `chcp` used inside a string.
static bool ParseStandaloneChcp(const W& line, int* cp, bool* hasNum) {
    W t = TrimL(line);
    if (!t.empty() && t[0] == L'@') t = TrimL(t.substr(1));
    if (t.empty() || t[0] == L':') return false;      // label / comment
    size_t p = 0;
    while (p < t.size() && !IsWs(t[p]) && t[p] != L'>' && t[p] != L'<' &&
           t[p] != L'&' && t[p] != L'|' && t[p] != L'(') ++p;
    W tok = Lower(t.substr(0, p));
    if (tok != L"chcp" && tok != L"chcp.com") return false;
    W rest = TrimL(t.substr(p));
    size_t k = 0;
    while (k < rest.size() && iswdigit(rest[k])) ++k;
    *hasNum = k > 0;
    *cp = k > 0 ? _wtoi(rest.substr(0, k).c_str()) : 0;
    return true;
}
static bool IsEchoOffLine(const W& line) {
    W t = Trim(line);
    if (!t.empty() && t[0] == L'@') t = TrimL(t.substr(1));
    return Lower(t) == L"echo off";
}
static void ManageChcp(std::vector<W>& lines, const Options& o, Report& r) {
    if (!o.manageChcp) { r.chcp = L"关闭"; return; }
    bool need = false, inlineChcp = false;
    std::vector<size_t> kill;
    int otherCp = 0, queryChcp = 0;
    for (size_t i = 0; i < lines.size(); ++i) {
        int cp = 0; bool hasNum = false;
        if (ParseStandaloneChcp(lines[i], &cp, &hasNum)) {
            // `chcp 936 & echo x` is a compound command: deleting the whole
            // line would silently drop the second command. Keep the line and
            // only normalise the codepage number in place.
            if (hasNum && lines[i].find_first_of(L"&|") != W::npos) {
                size_t a = lines[i].find_first_of(L"0123456789");
                if (a != W::npos) {
                    size_t b = a;
                    while (b < lines[i].size() && iswdigit(lines[i][b])) ++b;
                    lines[i] = lines[i].substr(0, a) + L"65001" + lines[i].substr(b);
                }
                inlineChcp = true;
                if (cp != 65001) otherCp = cp;
            } else {
                kill.push_back(i);
                if (hasNum) { if (cp != 65001) otherCp = cp; }
                else ++queryChcp;   // bare `chcp` only prints "Active code page"
            }
        }
        if (HasNonAscii(lines[i])) need = true;
    }
    if (!need && kill.empty() && !inlineChcp) { r.chcp = L"ASCII / 无需 chcp"; return; }
    if (inlineChcp && kill.empty()) { r.chcp = L"复合 chcp 已就地规范为 65001"; return; }

    // Drop ALL standalone chcp lines (numeric + bare query), then place one
    // canonical line where the user's own working scripts put it:
    //   line 1 @echo off  ->  line 2 chcp 65001 >nul   (no @ needed)
    //   otherwise         ->  line 1 @chcp 65001 >nul  (@ suppresses echo)
    // Idempotent: the canonical line is found and re-inserted at the same index.
    for (size_t j = kill.size(); j-- > 0;) lines.erase(lines.begin() + kill[j]);
    bool echoOffFirst = !lines.empty() && IsEchoOffLine(lines[0]);
    size_t at = echoOffFirst ? 1 : 0;
    lines.insert(lines.begin() + at, echoOffFirst ? W(L"chcp 65001 >nul") : W(L"@chcp 65001 >nul"));
    r.chcpTouched = (int)kill.size();
    r.chcp = L"chcp 65001 · 第 " + Itow((long long)at + 1) + L" 行 · 清理 " + Itow((long long)kill.size()) + L" 条";
    if (otherCp)
        r.Warn(L"chcp " + Itow(otherCp) + L" 已统一为 65001；若曾用它读写其它编码的外部文件请复核");
    if (queryChcp)
        r.Warn(L"已移除 " + Itow(queryChcp) + L" 条无参数 chcp（它会额外打印 Active code page）");
    if (kill.size() > 2) r.Warn(L"合并了 " + Itow((long long)kill.size()) + L" 条重复 chcp");
}

// ------------------------------------------------------------------ line tail fix
struct TailResult { W line; bool padded = false; bool rewritten = false; };

static bool IsCommentOrLabel(const W& t) {
    if (t.empty()) return false;
    if (t[0] == L':') return true;                                  // :: comment or :label
    if (StartsCI(t, L"rem") && (t.size() == 3 || IsWs(t[3]) || t[3] == L'.')) return true;
    return false;
}
static bool ParseSet(const W& body, W& opt, W& assign) {
    if (!StartsCI(body, L"set")) return false;
    if (body.size() > 3 && !IsWs(body[3]) && body[3] != L'"') return false;  // setx, setlocal...
    W rest = TrimL(body.substr(3));
    opt.clear();
    if (rest.size() >= 2 && rest[0] == L'/' && (towlower(rest[1]) == L'a' || towlower(rest[1]) == L'p')) {
        size_t q = 0; while (q < rest.size() && !IsWs(rest[q])) ++q;
        opt = rest.substr(0, q) + L" ";
        rest = TrimL(rest.substr(q));
    }
    if (rest.empty() || rest.find(L'=') == W::npos) return false;
    if (!rest.empty() && rest[0] == L'"') return false;   // already quoted
    if (rest.find_first_of(L"&|<>^\"") != W::npos) return false; // quoting would change meaning
    assign = rest;
    return true;
}
static bool TryQuoteRedirectTarget(const W& line, W& out) {
    size_t g = line.rfind(L'>');
    if (g == W::npos) return false;
    W tail = line.substr(g + 1);
    W tt = Trim(tail);
    if (tt.empty() || tt[0] == L'&') return false;               // 2>&1
    if (tt.find_first_of(L" \t&|<>\"^") != W::npos) return false;
    if (tt.back() <= 0x7F) return false;
    // keep operator + handle digit (2>, 1>, >>) + whitespace after '>'
    W ws;
    size_t q = g + 1;
    while (q < line.size() && IsWs(line[q])) { ws += line[q]; ++q; }
    out = line.substr(0, g + 1) + ws + L"\"" + tt + L"\"";
    return true;
}
static bool IsPathCommand(const W& low) {
    static const wchar_t* cmds[] = {
        L"cd ", L"chdir ", L"pushd ", L"del ", L"erase ", L"copy ", L"move ",
        L"ren ", L"rename ", L"md ", L"mkdir ", L"rd ", L"rmdir ", L"type ",
        L"attrib ", L"start "
    };
    for (auto c : cmds) if (StartsCI(low, c)) return true;
    return false;
}
static bool TryQuoteLastToken(const W& line, W& out) {
    size_t s = line.find_last_of(L" \t");
    if (s == W::npos) return false;
    W tok = line.substr(s + 1);
    if (tok.empty() || tok.back() <= 0x7F) return false;
    if (tok[0] == L'/' || tok[0] == L'"') return false;
    if (tok.find_first_of(L"\"&|<>^") != W::npos) return false;
    out = line.substr(0, s + 1) + L"\"" + tok + L"\"";
    return true;
}

// The ONLY lines that need a fix are those whose last byte before CRLF is a
// UTF-8 continuation byte (i.e. last character is non-ASCII). Lines ending
// with ASCII -- including '^' continuations, '(' / ')' block delimiters,
// quoted strings, redirect targets like .txt -- are left completely alone.
static TailResult FixTail(const W& line, const Options& o, Report& r) {
    TailResult res; res.line = line;
    if (!o.fixLineTail || line.empty()) return res;
    if (line.back() <= 0x7F) return res;   // already byte-safe

    W lead = line.substr(0, line.size() - TrimL(line).size());
    W body = TrimL(line);
    bool at = false;
    if (!body.empty() && body[0] == L'@') { at = true; body = TrimL(body.substr(1)); }

    // 1. comments / labels: a trailing space is completely inert
    if (IsCommentOrLabel(body)) { res.line = line + L" "; res.padded = true; return res; }

    // 2. set NAME=VALUE (unquoted): rewrite to the quoted form so the line
    //    ends with an ASCII quote. Value is preserved exactly, no trailing space.
    W opt, assign;
    if (ParseSet(body, opt, assign)) {
        res.line = lead + (at ? L"@" : L"") + L"set " + opt + L"\"" + assign + L"\"";
        res.rewritten = true;
        return res;
    }

    // 3. redirection whose target is the final token (e.g. echo 文本>结果)
    W q;
    if (TryQuoteRedirectTarget(line, q)) { res.line = q; res.rewritten = true; return res; }

    // 4. path-like commands whose final argument is a non-ASCII name
    if (IsPathCommand(Lower(body)) && TryQuoteLastToken(line, q)) {
        res.line = q; res.rewritten = true; return res;
    }

    // 5. goto / call :label -- trailing space is ignored by label lookup,
    //    but flag it so the user can double check.
    if (StartsCI(Lower(body), L"goto ") || StartsCI(Lower(body), L"call :"))
        r.Warn(L"含非 ASCII 标签的 goto/call 行已补空格，请确认标签跳转仍正常");

    // 6. everything else (echo / title / if / for / ...) -- one ASCII space.
    //    For `echo` this adds one invisible trailing space to the output.
    res.line = line + L" ";
    res.padded = true;
    return res;
}

// ------------------------------------------------------------------ mojibake (opt-in)
static bool LooksLikeMojibake(const W& s) {
    static const W sig = L"浣犲ソ涓鏄鐨勶銆嬶宀唬鐮椤鍒囨崲娴嬭瘯绗﹀彿锛氾紝锛涖€佲€濄€樿€欓敊璇姝ｅ父鏄剧ず鏂囦欢瀛楃爜涔辫姝ｇ‘缂栫爜";
    int hits = 0;
    for (wchar_t c : s) if (sig.find(c) != W::npos) { if (++hits >= 2) return true; }
    return false;
}
static bool TryRepairMojibake(W& text) {
    if (!LooksLikeMojibake(text)) return false;
    Bytes b;
    if (!WideToAnsi(936, text, b)) return false;
    W w2;
    if (!Utf8ToWide(b.data(), (int)b.size(), w2, true)) return false;
    if (w2.empty() || w2.size() >= text.size()) return false;
    int cjk = 0;
    for (wchar_t c : w2) if (c >= 0x4E00 && c <= 0x9FFF) ++cjk;
    if (!cjk) return false;
    text = w2;
    return true;
}

// ------------------------------------------------------------------ file IO
static bool ReadAll(const W& path, Bytes& data, W& err) {
    HANDLE h = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE,
                           nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) { err = L"无法打开(错误 " + Itow(GetLastError()) + L")"; return false; }
    LARGE_INTEGER sz;
    if (!GetFileSizeEx(h, &sz)) { CloseHandle(h); err = L"无法读取文件大小"; return false; }
    if (sz.QuadPart > (LONGLONG)(64u * 1024u * 1024u)) { CloseHandle(h); err = L"文件超过 64 MB，已跳过"; return false; }
    data.resize((size_t)sz.QuadPart);
    DWORD got = 0;
    if (!data.empty() && !ReadFile(h, &data[0], (DWORD)data.size(), &got, nullptr)) {
        CloseHandle(h); err = L"读取失败"; return false;
    }
    data.resize(got);
    CloseHandle(h);
    return true;
}
static bool WriteAll(const W& path, const Bytes& data, W& err) {
    DWORD attr = GetFileAttributesW(path.c_str());
    bool ro = (attr != INVALID_FILE_ATTRIBUTES) && (attr & FILE_ATTRIBUTE_READONLY);
    if (ro) SetFileAttributesW(path.c_str(), attr & ~FILE_ATTRIBUTE_READONLY);
    HANDLE h = CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS,
                           FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) {
        if (ro) SetFileAttributesW(path.c_str(), attr);
        err = L"无法写入(错误 " + Itow(GetLastError()) + L")";
        return false;
    }
    DWORD wrote = 0;
    BOOL ok = data.empty() ? TRUE : WriteFile(h, data.data(), (DWORD)data.size(), &wrote, nullptr);
    CloseHandle(h);
    if (ro) SetFileAttributesW(path.c_str(), attr);
    if (!ok || wrote != data.size()) { err = L"写入不完整"; return false; }
    return true;
}
static bool MakeBackup(const W& src, W& bakPath, W& err) {
    for (int i = 0; i < 1000; ++i) {
        W cand = src + (i == 0 ? L".bak" : L".bak." + Itow(i));
        if (GetFileAttributesW(cand.c_str()) == INVALID_FILE_ATTRIBUTES) {
            if (CopyFileW(src.c_str(), cand.c_str(), TRUE)) { bakPath = cand; return true; }
            err = L"备份失败(错误 " + Itow(GetLastError()) + L")";
            return false;
        }
    }
    err = L"备份文件过多";
    return false;
}

// ------------------------------------------------------------------ convert one file
static bool ConvertOne(const W& inPath, const W& outPath, const Options& o, Report& r) {
    r.path = inPath;
    Bytes raw; W err;
    if (!ReadAll(inPath, raw, err)) { r.result = L"ERR"; r.message = err; return false; }
    if (raw.size() > o.maxBytes) { r.result = L"SKIP"; r.message = L"超过大小上限，已跳过"; return true; }

    AnalyzeNewline(raw, r.newline);
    Decoded d = DecodeFile(raw, o, r);
    r.enc = d.name;
    if (d.e == Enc::Binary) {
        r.result = L"SKIP";
        r.message = L"疑似二进制/编码无法判定，未改动";
        return true;
    }
    if (o.repairMojibake && TryRepairMojibake(d.text))
        r.Warn(L"已尝试还原“UTF-8 被按 GBK 误读”类型的乱码文本，请人工核对");
    else if (LooksLikeMojibake(d.text))
        r.Warn(L"文本疑似已是乱码(mojibake)；可勾选“尝试修复已乱码文本”后重新转换");

    if (HasNonBmp(d.text))
        r.Warn(L"含非 BMP 字符(如 emoji)：UTF-8 编码已正确，但传统 conhost 字体可能显示为方框，建议在 Windows Terminal 中运行");

    std::vector<W> lines = SplitLines(d.text);
    ManageChcp(lines, o, r);

    for (size_t i = 0; i < lines.size(); ++i) {
        TailResult t = FixTail(lines[i], o, r);
        lines[i] = t.line;
        if (t.padded) ++r.padded;
        if (t.rewritten) ++r.rewritten;
        if (lines[i].size() > 8100)
            r.Warn(L"第 " + Itow((long long)i + 1) + L" 行超过 8100 字符，接近 cmd 的 8191 上限");
    }

    W joined;
    for (size_t i = 0; i < lines.size(); ++i) {
        if (i) joined += L"\r\n";
        joined += lines[i];
    }
    if (o.normalizeNewline && !lines.empty() && o.ensureTrailingCrlf) joined += L"\r\n";
    if (!o.normalizeNewline) {
        // Keep original line endings but still remove BOM: rebuild from raw.
        // (This mode is intentionally conservative; chcp/tail fixes need CRLF,
        //  so it is only offered for completeness.)
        joined.clear();
        for (size_t i = 0; i < lines.size(); ++i) {
            if (i) joined += L"\n";
            joined += lines[i];
        }
    }

    Bytes out;
    if (!WideToUtf8(joined, out)) { r.result = L"ERR"; r.message = L"UTF-8 编码失败"; return false; }

    // ALWAYS snapshot the original for an in-place run, BEFORE deciding
    // whether any bytes actually need writing. A file that is already
    // compliant still gets a backup every time the user explicitly runs
    // the converter over it.
    bool inplace = (outPath == inPath);
    if (inplace && o.backup) {
        W bak, berr;
        if (!MakeBackup(inPath, bak, berr)) {
            r.result = L"ERR"; r.message = berr; return false;
        }
        r.backedUp = true;
        r.backupPath = bak;
        r.Warn(L"原文件已备份为 " + Basename(bak));
    }

    if (out == raw) {
        r.result = L"OK";
        if (outPath != inPath) {
            // --out mode: still emit the file so the output dir is complete.
            W err2;
            if (!WriteAll(outPath, out, err2)) { r.result = L"ERR"; r.message = err2; return false; }
            r.message = L"已符合规范，内容原样写出";
        } else {
            r.message = L"已符合规范，无需修改";
        }
        return true;
    }
    if (!WriteAll(outPath, out, err)) { r.result = L"ERR"; r.message = err; return false; }
    r.changed = true;
    r.message = L"已转换";
    return true;
}

// ------------------------------------------------------------------ report formatting
static W ReportLine(const Report& r) {
    W s = L"[" + r.result + L"] " + r.path + L"\r\n";
    s += L"    编码: " + r.enc + L"   BOM: " + r.bom + L"   换行: " + r.newline + L"\r\n";
    s += L"    chcp: " + r.chcp + L"   补空格: " + Itow(r.padded) +
         L" 行   智能重写: " + Itow(r.rewritten) + L" 行\r\n";
    if (!r.message.empty()) s += L"    " + r.message + L"\r\n";
    for (const W& w : r.warns) s += L"    ! " + w + L"\r\n";
    return s;
}
static W ReportTsv(const Report& r) {
    W s = r.path + L"\tENC=" + r.enc + L"\tBOM=" + r.bom + L"\tNL=" + r.newline +
          L"\tCHCP=" + r.chcp + L"\tPAD=" + Itow(r.padded) +
          L"\tREWRITE=" + Itow(r.rewritten) +
          L"\tBACKUP=" + (r.backedUp ? Basename(r.backupPath) : L"-") +
          L"\tRESULT=" + r.result + L"\tMSG=" + r.message;
    for (const W& w : r.warns) s += L"\tWARN=" + w;
    return s + L"\n";
}

// ------------------------------------------------------------------ file collection
static void CollectPath(const W& path, std::vector<W>& out, int depth = 0) {
    DWORD a = GetFileAttributesW(path.c_str());
    if (a == INVALID_FILE_ATTRIBUTES) return;
    if (a & FILE_ATTRIBUTE_DIRECTORY) {
        if (depth > 8) return;
        WIN32_FIND_DATAW fd;
        HANDLE h = FindFirstFileW((path + L"\\*").c_str(), &fd);
        if (h == INVALID_HANDLE_VALUE) return;
        do {
            W n = fd.cFileName;
            if (n == L"." || n == L"..") continue;
            CollectPath(path + L"\\" + n, out, depth + 1);
        } while (FindNextFileW(h, &fd));
        FindClose(h);
    } else if (IsBatFile(path)) {
        if (std::find(out.begin(), out.end(), path) == out.end()) out.push_back(path);
    }
}
static W JoinOutDir(const W& dir, const W& src) {
    return dir + (dir.empty() || dir.back() == L'\\' ? L"" : L"\\") + Basename(src);
}

// ------------------------------------------------------------------ CLI mode
static HANDLE g_reportFile = INVALID_HANDLE_VALUE;
static void CliWrite(const W& text) {
    Bytes b; WideToUtf8(text, b);
    if (g_reportFile != INVALID_HANDLE_VALUE) {
        DWORD w; WriteFile(g_reportFile, b.data(), (DWORD)b.size(), &w, nullptr);
    }
    HANDLE h = GetStdHandle(STD_OUTPUT_HANDLE);
    if (h && h != INVALID_HANDLE_VALUE) { DWORD w; WriteFile(h, b.data(), (DWORD)b.size(), &w, nullptr); }
}
static int RunCli(int argc, wchar_t** argv, const Options& defaults) {
    Options o = defaults;
    W outDir, reportPath;
    std::vector<W> inputs;
    for (int i = 1; i < argc; ++i) {
        W a = argv[i];
        if (a == L"--out" && i + 1 < argc) outDir = argv[++i];
        else if (a == L"--report" && i + 1 < argc) reportPath = argv[++i];
        else if (a == L"--no-backup") o.backup = false;
        else if (a == L"--mojibake") o.repairMojibake = true;
        else if (a == L"--no-chcp") o.manageChcp = false;
        else if (a == L"--no-tail") o.fixLineTail = false;
        else if (a == L"--no-newline") o.normalizeNewline = false;
        else if (a == L"--cp" && i + 1 < argc) o.ansiCp = (UINT)_wtoi(argv[++i]);
        else if (a == L"--cli") { /* marker */ }
        else inputs.push_back(a);
    }
    if (!reportPath.empty()) {
        g_reportFile = CreateFileW(reportPath.c_str(), GENERIC_WRITE, FILE_SHARE_READ,
                                   nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    }
    // --out with a non-existent directory used to fail with a bare "error 3".
    if (!outDir.empty() && GetFileAttributesW(outDir.c_str()) == INVALID_FILE_ATTRIBUTES)
        CreateDirectoryW(outDir.c_str(), nullptr);
    AttachConsole(ATTACH_PARENT_PROCESS);

    std::vector<W> files;
    for (const W& p : inputs) CollectPath(p, files);
    CliWrite(L"BatFix v" + W(BATFIX_VERSION_WTEXT) + L"  files=" +
             Itow((long long)files.size()) + L"\n");
    int errors = 0;
    for (const W& f : files) {
        W dest = outDir.empty() ? f : JoinOutDir(outDir, f);
        Report r;
        bool ok = ConvertOne(f, dest, o, r);
        if (!ok) ++errors;
        CliWrite(ReportTsv(r));
    }
    CliWrite(L"SUMMARY files=" + Itow((long long)files.size()) + L" errors=" + Itow(errors) + L"\n");
    if (g_reportFile != INVALID_HANDLE_VALUE) CloseHandle(g_reportFile);
    return errors ? 1 : 0;
}

